const draw = () => {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw ship (triangle pointing up)
  ctx.fillStyle = '#0af';
  ctx.beginPath();
  ctx.moveTo(ship.x, ship.y - ship.size);
  ctx.lineTo(ship.x - ship.size, ship.y + ship.size);
  ctx.lineTo(ship.x + ship.size, ship.y + ship.size);
  ctx.closePath();
  ctx.fill();

  // Draw debris
  ctx.fillStyle = '#a33';
  debris.forEach(d => {
    ctx.beginPath();
    ctx.arc(d.x, d.y, d.radius, 0, Math.PI * 2);
    ctx.fill();
  });

  // Draw score
  ctx.fillStyle = '#000';
  ctx.font = '16px sans-serif';
  ctx.fillText(`Time: ${elapsed.toFixed(1)}s`, 10, 20);

  // Draw laser cooldown indicator
  if (laserCooldown > 0) {
    ctx.fillText(`Laser: ${laserCooldown.toFixed(1)}s`, 10, 40);
  }
};

